style.css:
@-moz-document domain("roblox.com") {
body::before {
    content: "";
    position: fixed;
    top: 0;
    left: 0;
    width: 100%;
    height: 100%;
    background-size: cover;
    background-position: center;
    filter: blur(10px);
    z-index: -1;
  }

  body {
    position: relative;
    z-index: 0;
  }
}
